def write(path, obj):
 p=HERE/path
 p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')

def source(suffix,title,url,note,status='supporting_page_checked'):
 return dict(id='dc165_'+suffix,title=title,citation=title,url=url,
             verification=dict(status=status,checked_on=DAY,note=note))

def event(suffix,label,year,sids,support,kind='publication',track='contributions'):
 return dict(id='dc165_'+suffix,label=label,kind=kind,track=track,
             date=dict(year=year,precision='year'),source_ids=['graph:'+i for i in sids],support=support)

